var FEEDBOX={on:0,x:0,y:0,w:0,h:0,rows:[]};
// v16.xx (feed3), HIS ORDER (2026-10-14): THE OLD PLACES ARE GONE. Everything they showed is a line in the feed (feed1), so they are not
// drawn any more: the message rows at the top centre (MSGROWS), the pickup stack at the right edge (PICKDRAW), the co-op kill feed at the
// right edge (NETFEEDDRAW), the rising loot names and other message labels at the world (a label that is a line in the feed is hidden:
// feedHides) and the medal plates over the cursor (STYPLATE; the combo ring stays). The data they read is kept as it was (G.msg,
// G.feed, G.pick, NET.feed, G.labels, the medal list), so nothing that reads it moves; only the drawing stops. Hit feedback stays on
// its target: WEAK SPOT, ACTIVE RELOAD, CLOSE CALL and PICKED UP are still world labels. The alert lane, the location tag, the boss
// bar and the prompts are not touched.
var MSGROWS=0, PICKDRAW=0, NETFEEDDRAW=0, STYPLATE=0;
function feedHides(txt){ return !(/^(WEAK SPOT|ACTIVE RELOAD|PICKED UP|CLOSE CALL)$/).test(String(txt)); }

check:
{v:'VER',what:'his order: the old places are gone: the message rows at the top centre, the pickup stack and kill feed at the right edge, the rising loot names and the cursor medal plates are not drawn, the same lines show in the feed, and hit feedback (WEAK SPOT) stays on its target',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||!window.__textTrace) return 'SKIP: no raid here';
   if(typeof feedAdd!=='function'||typeof styMedal!=='function'||typeof careerPostBuild!=='function') return 'SKIP: no feed here';
   var bad=[], g, p, tr, i, ZW, at;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     try{ careerPostBuild(g); }catch(_c){}
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; p=g.player; p.iv=99;
     say('Scrap Metal','pick',{item:'scrap',n:2});
     say('CACHE MARKED','obj',{sub:'TEAMMATE PINGED A STRONGBOX'});
     label(p.x+40,p.y-30,'FEED3 LOOT NAME','#9da3a8',0,false,'scrap');
     label(p.x-40,p.y-30,'WEAK SPOT','#ff6b5a',0,true);
     styMedal('LONG SHOT',100,p.x,p.y);
     for(i=0;i<3;i++) __frame(0.016);
     tr=__textTrace(function(){ __frame(0.016); });
     ZW=W*0.3;
     at=function(t){ return tr.filter(function(e){ return e.t.indexOf(t)===0; }); };
     if(!at('CACHE MARKED').length) bad.push('the objective line is not drawn anywhere'); else if(at('CACHE MARKED').some(function(e){ return e.x>ZW; })) bad.push('the objective line is still drawn outside the feed (at '+Math.round(at('CACHE MARKED')[0].x)+')');
     if(!at('Scrap Metal').length) bad.push('the pickup is not drawn anywhere'); else if(at('Scrap Metal').some(function(e){ return e.x>ZW; })) bad.push('the pickup is still drawn outside the feed (at '+Math.round(at('Scrap Metal')[0].x)+')');
     if(at('LONG SHOT').length===0) bad.push('the medal is not drawn anywhere'); else if(at('LONG SHOT').some(function(e){ return e.x>ZW; })) bad.push('the medal plate is still drawn at the cursor (at '+Math.round(at('LONG SHOT')[0].x)+')');
     if(at('FEED3 LOOT NAME').length) bad.push('a rising loot name is still drawn at the world');
     if(!at('WEAK SPOT').length) bad.push('WEAK SPOT is no longer drawn on its target');
     if(EDGEBOX.pick) bad.push('the pickup stack still has a box at the right edge');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var g2=__state(); if(g2&&!g2.over){ g2.player.iv=0; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
